 of a locale to support	kAllRegions,			// inherited regionCode - regionCode to try as a backup to this one. kAllRegions if none.	// Offset Mappings	{		'****',				// resourceID - the type of resource, may be '****' for wildcard		kverUSOffset		// IDOffset - the offset to add to ID for resources that support this locale	},		// Direct Mappings - None	{ }};